from __future__ import annotations

from dataclasses import asdict
from typing import Any

from homeassistant.components.diagnostics import async_redact_data
from homeassistant.const import CONF_PASSWORD
from homeassistant.core import HomeAssistant

from .coordinator import FreshrConfigEntry

TO_REDACT = {CONF_PASSWORD}


async def async_get_config_entry_diagnostics(
    hass: HomeAssistant, entry: FreshrConfigEntry
) -> dict[str, Any]:
    """Return diagnostics for a Fresh-r config entry."""
    data = entry.runtime_data

    return {
        "entry": async_redact_data(entry.data, TO_REDACT),
        "devices": [asdict(device) for device in data.devices.data.values()],
        "readings": {
            device_id: asdict(coordinator.data)
            for device_id, coordinator in data.readings.items()
        },
    }
